const originalFetch = window.fetch;
window._apiCalls = [];
window.fetch = async function(...args) {
  const [url, options] = args;
  const callInfo = { url: typeof url === 'string' ? url : url.url, method: options?.method || 'GET' };
  if (options?.body) {
    try { callInfo.body = JSON.parse(options.body); } catch(e) { callInfo.body = options.body; }
  }
  if (options?.headers) {
    callInfo.headers = Object.fromEntries(
      options.headers instanceof Headers ? options.headers.entries() :
      Array.isArray(options.headers) ? options.headers :
      Object.entries(options.headers)
    );
  }
  const response = await originalFetch.apply(this, args);
  const clone = response.clone();
  try {
    const data = await clone.json();
    callInfo.response = data;
  } catch(e) {}
  window._apiCalls.push(callInfo);
  return response;
};
